INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 39, 'theory', 'Quiz: bits, bytes and an emulator');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 0, 'What is 300i32 as u8 in Rust?', '["300", "255", "44", "a panic"]', 2, 'Narrowing drops the high bits: 300 mod 256 = 44.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 1, 'How do you write a number into bytes in network order (most significant first) in Rust?', '["n.to_le_bytes()", "n.to_be_bytes()", "n.as_bytes()", "n.swap()"]', 1, 'be means big-endian; the order is stated in the method name.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 2, 'Why does a struct { u8, u32, u8 } in Rust usually take 8 bytes, and 12 with #[repr(C)]?', '["A compiler bug", "Rust may reorder fields to reduce padding; repr(C) fixes the C order", "repr(C) compresses the data", "It depends on the OS"]', 1, 'Each field is aligned to its type; reordering removes the empty bytes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 3, 'What does the high bit of a byte hold in a varint (LEB128)?', '["The sign of the number", "The continuation flag: whether another byte follows", "A checksum", "Nothing"]', 1, 'The other seven bits are pieces of the number, so small values take one byte.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 4, 'Why do the emulator''s memory access errors return Result<_, Trap> instead of panicking?', '["It is faster", "A wrong program is not a bug of the emulator: it must raise an \"interrupt\", while the emulator keeps working", "Panics are forbidden", "Result cannot be used in loops"]', 1, 'This way the emulator behaves like a real processor: it reports a trap instead of crashing.');
